import React, { useState, useEffect } from 'react'
import { useParams, useLocation, useNavigate } from 'react-router-dom'
import { supabase, TABLES } from '../supabase'
import toast from 'react-hot-toast'

const JudgePanel = () => {
  const { eventId } = useParams()
  const location = useLocation()
  const navigate = useNavigate()
  const { judgeId, judgeName, event } = location.state || {}

  // State management
  const [loading, setLoading] = useState(true)
  const [eventData, setEventData] = useState(null)
  const [criteria, setCriteria] = useState([])
  const [candidates, setCandidates] = useState([])
  const [specialAwards, setSpecialAwards] = useState([])
  
  // Scoring states
  const [criteriaScores, setCriteriaScores] = useState({}) // {candidateId-criteriaId: score}
  const [awardScores, setAwardScores] = useState({}) // {candidateId-awardId: score}
  
  // Completion tracking
  const [completedCriteria, setCompletedCriteria] = useState(new Set())
  const [completedAwards, setCompletedAwards] = useState(new Set())
  
  // UI states - only one can be expanded at a time
  const [expandedCriteria, setExpandedCriteria] = useState(null)
  const [expandedAwards, setExpandedAwards] = useState(null)
  const [submitting, setSubmitting] = useState(false)
  const [showConfirmationModal, setShowConfirmationModal] = useState(false)
  const [pendingSubmission, setPendingSubmission] = useState(null) // {type: 'criteria'|'award', id: string}

  // Load event data on component mount
  useEffect(() => {
    if (event) {
      loadEventData()
    } else {
      fetchEventData()
    }
  }, [eventId])

  const loadEventData = async () => {
    try {
      setLoading(true)
      
      // Load criteria
      const { data: criteriaData, error: criteriaError } = await supabase
        .from(TABLES.CRITERIA)
        .select('*')
        .eq('event_id', eventId)
        .order('created_at')

      if (criteriaError) throw criteriaError

      // Load candidates
      const { data: candidatesData, error: candidatesError } = await supabase
        .from(TABLES.CANDIDATES)
        .select('*')
        .eq('event_id', eventId)
        .order('candidate_number')

      if (candidatesError) throw candidatesError

      // Load special awards
      const { data: awardsData, error: awardsError } = await supabase
        .from(TABLES.SPECIAL_AWARDS)
        .select('*')
        .eq('event_id', eventId)
        .eq('award_type', 'vote')
        .order('created_at')

      if (awardsError) {
        console.warn('No special awards found:', awardsError)
      }

      // Load existing scores
      await loadExistingScores()

      setCriteria(criteriaData || [])
      setCandidates(candidatesData || [])
      setSpecialAwards(awardsData || [])
      setEventData(event)
      
    } catch (error) {
      console.error('Error loading event data:', error)
      toast.error('Failed to load event data')
      navigate('/access-event')
    } finally {
      setLoading(false)
    }
  }

  const fetchEventData = async () => {
    try {
      setLoading(true)
      
      // Fetch event details
      const { data: eventData, error: eventError } = await supabase
        .from(TABLES.EVENTS)
        .select('*')
        .eq('id', eventId)
        .single()

      if (eventError) throw eventError

      // Load criteria
      const { data: criteriaData, error: criteriaError } = await supabase
        .from(TABLES.CRITERIA)
        .select('*')
        .eq('event_id', eventId)
        .order('created_at')

      if (criteriaError) throw criteriaError

      // Load candidates
      const { data: candidatesData, error: candidatesError } = await supabase
        .from(TABLES.CANDIDATES)
        .select('*')
        .eq('event_id', eventId)
        .order('candidate_number')

      if (candidatesError) throw candidatesError

      // Load special awards
      const { data: awardsData, error: awardsError } = await supabase
        .from(TABLES.SPECIAL_AWARDS)
        .select('*')
        .eq('event_id', eventId)
        .eq('award_type', 'vote')
        .order('created_at')

      if (awardsError) {
        console.warn('No special awards found:', awardsError)
      }

      // Load existing scores
      await loadExistingScores()

      setCriteria(criteriaData || [])
      setCandidates(candidatesData || [])
      setSpecialAwards(awardsData || [])
      setEventData(eventData)
      
    } catch (error) {
      console.error('Error fetching event data:', error)
      toast.error('Failed to load event data')
      navigate('/access-event')
    } finally {
      setLoading(false)
    }
  }

  const loadExistingScores = async () => {
    try {
      // Load judge's completion status from the judges table
      const { data: judgeData, error: judgeError } = await supabase
        .from(TABLES.JUDGES)
        .select('completed_criteria, submitted_special_awards')
        .eq('id', judgeId)
        .single()

      if (judgeError) {
        console.warn('Could not load judge completion status:', judgeError)
      }

      // Load criteria scores
      const { data: criteriaScoresData, error: criteriaScoresError } = await supabase
        .from(TABLES.SCORES)
        .select('*')
        .eq('event_id', eventId)
        .eq('judge_id', judgeId)

      if (criteriaScoresError) throw criteriaScoresError

      // Load award scores
      const { data: awardScoresData, error: awardScoresError } = await supabase
        .from(TABLES.SPECIAL_AWARD_VOTES)
        .select('*')
        .eq('judge_id', judgeId)

      if (awardScoresError) {
        console.warn('No award scores found:', awardScoresError)
      }

      // Process criteria scores
      const criteriaScoresMap = {}
      
      if (criteriaScoresData) {
        criteriaScoresData.forEach(score => {
          const key = `${score.candidate_id}-${score.criteria_id}`
          criteriaScoresMap[key] = score.score
        })
      }

      // Process award scores
      const awardScoresMap = {}
      
      if (awardScoresData) {
        awardScoresData.forEach(score => {
          const key = `${score.candidate_id}-${score.special_award_id}`
          awardScoresMap[key] = score.score
        })
      }

      // Load completion status from database
      const completedCriteriaSet = new Set(judgeData?.completed_criteria || [])
      const completedAwardsSet = new Set(judgeData?.submitted_special_awards || [])

      console.log('Loaded judge completion status:', {
        completedCriteria: Array.from(completedCriteriaSet),
        completedAwards: Array.from(completedAwardsSet),
        judgeData
      })

      setCriteriaScores(criteriaScoresMap)
      setAwardScores(awardScoresMap)
      setCompletedCriteria(completedCriteriaSet)
      setCompletedAwards(completedAwardsSet)

    } catch (error) {
      console.error('Error loading existing scores:', error)
    }
  }

  // Criteria scoring functions
  const handleCriteriaScoreChange = (candidateId, criteriaId, score) => {
    const criterion = criteria.find(c => c.id === criteriaId)
    const maxScore = criterion ? criterion.percentage : 100
    const normalizedScore = Math.min(Math.max(parseInt(score) || 0, 0), maxScore)
    
    const key = `${candidateId}-${criteriaId}`
    setCriteriaScores(prev => ({
      ...prev,
      [key]: normalizedScore
    }))
  }

  const isCriteriaComplete = (criteriaId) => {
    return completedCriteria.has(criteriaId)
  }

  const canSubmitCriteria = (criteriaId) => {
    return candidates.every(candidate => {
      const key = `${candidate.id}-${criteriaId}`
      return criteriaScores[key] !== undefined && criteriaScores[key] !== null
    })
  }

  const handleSubmitCriteriaClick = (criteriaId) => {
    if (!canSubmitCriteria(criteriaId)) {
      toast.error('Please provide scores for all candidates')
      return
    }
    
    setPendingSubmission({ type: 'criteria', id: criteriaId })
    setShowConfirmationModal(true)
  }

  const submitCriteriaScores = async (criteriaId) => {
    setSubmitting(true)
    setShowConfirmationModal(false)
    
    try {
      const scoreData = candidates.map(candidate => ({
        event_id: eventId,
        judge_id: judgeId,
        candidate_id: candidate.id,
        criteria_id: criteriaId,
        score: criteriaScores[`${candidate.id}-${criteriaId}`] || 0
      }))

      const { error } = await supabase
        .from(TABLES.SCORES)
        .insert(scoreData)

      if (error) throw error

      // Update judge's completed criteria in the database
      const newCompletedCriteria = new Set([...completedCriteria, criteriaId])
      const { error: updateError } = await supabase
        .from(TABLES.JUDGES)
        .update({ completed_criteria: Array.from(newCompletedCriteria) })
        .eq('id', judgeId)

      if (updateError) {
        console.error('Error updating judge completion status:', updateError)
        throw new Error('Failed to update completion status')
      }

      setCompletedCriteria(newCompletedCriteria)
      toast.success('Criteria scores submitted successfully!')
      
    } catch (error) {
      console.error('Error submitting criteria scores:', error)
      toast.error('Failed to submit scores')
    } finally {
      setSubmitting(false)
      setPendingSubmission(null)
    }
  }

  // Award scoring functions
  const handleAwardScoreChange = (candidateId, awardId, score) => {
    const normalizedScore = Math.min(Math.max(parseInt(score) || 0, 0), 100)
    
    const key = `${candidateId}-${awardId}`
    setAwardScores(prev => ({
      ...prev,
      [key]: normalizedScore
    }))
  }

  const isAwardComplete = (awardId) => {
    return completedAwards.has(awardId)
  }

  const canSubmitAward = (awardId) => {
    return candidates.every(candidate => {
      const key = `${candidate.id}-${awardId}`
      return awardScores[key] !== undefined && awardScores[key] !== null
    })
  }

  const handleSubmitAwardClick = (awardId) => {
    if (!canSubmitAward(awardId)) {
      toast.error('Please provide scores for all candidates')
      return
    }
    
    setPendingSubmission({ type: 'award', id: awardId })
    setShowConfirmationModal(true)
  }

  const submitAwardScores = async (awardId) => {
    setSubmitting(true)
    setShowConfirmationModal(false)
    
    try {
      // Delete existing scores for this award
      await supabase
        .from(TABLES.SPECIAL_AWARD_VOTES)
        .delete()
        .eq('judge_id', judgeId)
        .eq('special_award_id', awardId)

      const scoreData = candidates.map(candidate => ({
        special_award_id: awardId,
        judge_id: judgeId,
        candidate_id: candidate.id,
        score: awardScores[`${candidate.id}-${awardId}`] || 0
      }))

      const { error } = await supabase
        .from(TABLES.SPECIAL_AWARD_VOTES)
        .insert(scoreData)

      if (error) throw error

      // Update judge's submitted special awards in the database
      const newCompletedAwards = new Set([...completedAwards, awardId])
      const { error: updateError } = await supabase
        .from(TABLES.JUDGES)
        .update({ submitted_special_awards: Array.from(newCompletedAwards) })
        .eq('id', judgeId)

      if (updateError) {
        console.error('Error updating judge special awards status:', updateError)
        throw new Error('Failed to update completion status')
      }

      setCompletedAwards(newCompletedAwards)
      toast.success('Award scores submitted successfully!')
      
    } catch (error) {
      console.error('Error submitting award scores:', error)
      toast.error('Failed to submit scores')
    } finally {
      setSubmitting(false)
      setPendingSubmission(null)
    }
  }

  // UI helper functions - single expansion behavior
  const toggleCriteriaExpansion = (criteriaId) => {
    setExpandedCriteria(prev => prev === criteriaId ? null : criteriaId)
    // Close awards when opening criteria
    if (expandedAwards) {
      setExpandedAwards(null)
    }
  }

  const toggleAwardExpansion = (awardId) => {
    setExpandedAwards(prev => prev === awardId ? null : awardId)
    // Close criteria when opening awards
    if (expandedCriteria) {
      setExpandedCriteria(null)
    }
  }

  const handleConfirmSubmission = () => {
    if (pendingSubmission?.type === 'criteria') {
      submitCriteriaScores(pendingSubmission.id)
    } else if (pendingSubmission?.type === 'award') {
      submitAwardScores(pendingSubmission.id)
    }
  }

  const handleCancelSubmission = () => {
    setShowConfirmationModal(false)
    setPendingSubmission(null)
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-500 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading judge panel...</p>
        </div>
      </div>
    )
  }

  if (!eventData || !judgeId) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <p className="text-red-600 mb-4">Access denied. Please use the proper event access flow.</p>
          <button 
            onClick={() => navigate('/access-event')}
            className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600"
          >
            Back to Access Event
          </button>
        </div>
      </div>
    )
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-6xl mx-auto px-4">
        {/* Header */}
        <div className="bg-gradient-to-br from-blue-50 to-indigo-100 rounded-2xl shadow-lg border border-blue-200 p-8 mb-8">
          <div className="text-center">
            {/* Event Logo */}
            {eventData.logo_url && (
              <div className="mb-6">
                <img 
                  src={eventData.logo_url} 
                  alt="Event Logo" 
                  className="w-24 h-24 mx-auto rounded-2xl object-cover shadow-xl border-4 border-white"
                />
              </div>
            )}
            
            {/* Event Name */}
            <h2 className="text-3xl font-bold text-gray-900 mb-4">{eventData.name}</h2>
            
            {/* Judge Panel Title with Icon */}
            <div className="flex items-center justify-center gap-3 mb-4">
              <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <h1 className="text-4xl font-bold text-gray-900">Judge Panel</h1>
            </div>
            
            {/* Welcome Message with Badge */}
            <div className="inline-flex items-center gap-3 bg-white rounded-full px-6 py-3 shadow-md border border-blue-200">
              <div className="w-8 h-8 bg-green-100 rounded-full flex items-center justify-center">
                <svg className="w-5 h-5 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                </svg>
              </div>
              <span className="text-lg font-semibold text-gray-700">Welcome, {judgeName}</span>
            </div>
          </div>
        </div>

        {/* Criteria Section */}
        <div className="mb-8">
          <div className="flex items-center gap-4 mb-8">
            <div className="w-12 h-12 bg-gradient-to-br from-blue-500 to-blue-600 rounded-2xl flex items-center justify-center shadow-lg">
              <svg className="w-7 h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
            </div>
            <div>
              <h2 className="text-3xl font-bold text-gray-900">Evaluation Criteria</h2>
              <p className="text-gray-600 mt-1">Score each candidate based on the following criteria</p>
            </div>
          </div>
          
          <div className="space-y-4">
            {criteria.map((criterion) => {
              const isExpanded = expandedCriteria === criterion.id
              const isCompleted = isCriteriaComplete(criterion.id)
              
              return (
                <div key={criterion.id} className={`bg-white rounded-2xl shadow-lg border-2 transition-all duration-300 ${
                  isExpanded ? 'border-blue-300 shadow-xl' : 'border-gray-200 hover:border-blue-200'
                }`}>
                  {/* Criteria Header */}
                  <div 
                    className="p-6 cursor-pointer hover:bg-gradient-to-r hover:from-blue-50 hover:to-indigo-50 transition-all duration-300 rounded-t-2xl"
                    onClick={() => toggleCriteriaExpansion(criterion.id)}
                  >
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-4 flex-wrap">
                        <div className="flex items-center gap-3">
                          <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
                            isCompleted ? 'bg-green-100' : 'bg-blue-100'
                          }`}>
                            {isCompleted ? (
                              <svg className="w-6 h-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                              </svg>
                            ) : (
                              <span className="text-blue-600 font-bold text-lg">{criterion.percentage}%</span>
                            )}
                          </div>
                          <div>
                            <h3 className="text-xl font-bold text-gray-900">{criterion.name}</h3>
                            <p className="text-sm text-gray-600">Maximum {criterion.percentage} points</p>
                          </div>
                        </div>
                        
                        <div className="flex items-center gap-2">
                          <span className={`px-4 py-2 rounded-full text-sm font-semibold ${
                            isCompleted 
                              ? 'bg-green-100 text-green-800 border border-green-200' 
                              : 'bg-blue-100 text-blue-800 border border-blue-200'
                          }`}>
                            {isCompleted ? '✓ Completed' : 'Pending'}
                          </span>
                        </div>
                      </div>
                      
                      <div className="flex items-center gap-3">
                        <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300 ${
                          isExpanded ? 'bg-blue-100 rotate-180' : 'bg-gray-100'
                        }`}>
                          <svg 
                            className="w-5 h-5 text-gray-600 transition-transform duration-300" 
                            fill="none" 
                            stroke="currentColor" 
                            viewBox="0 0 24 24"
                          >
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                          </svg>
                        </div>
                      </div>
                    </div>
                  </div>

                  {/* Expanded Content */}
                  {isExpanded && (
                    <div className="border-t border-gray-200 p-8 bg-gradient-to-br from-gray-50 to-blue-50 rounded-b-2xl">
                      <div className="bg-white rounded-xl p-6 shadow-sm border border-gray-200 mb-6">
                        <div className="flex items-center gap-3 mb-2">
                          <div className="w-8 h-8 bg-blue-100 rounded-lg flex items-center justify-center">
                            <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                            </svg>
                          </div>
                          <h4 className="text-lg font-semibold text-gray-900">Scoring Instructions</h4>
                        </div>
                        <p className="text-gray-700">Score each candidate from 0 to {criterion.percentage} points based on their performance in this criteria.</p>
                      </div>
                      
                      {/* Candidates Scoring */}
                      <div className="space-y-4 mb-8">
                        {candidates.map((candidate) => {
                          const scoreKey = `${candidate.id}-${criterion.id}`
                          const currentScore = criteriaScores[scoreKey] || 0
                          
                          return (
                            <div key={candidate.id} className="bg-white rounded-xl p-6 border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
                              <div className="flex items-center justify-between">
                                <div className="flex items-center gap-4">
                                  <div className="w-12 h-12 bg-gradient-to-br from-blue-500 to-blue-600 text-white rounded-xl flex items-center justify-center text-lg font-bold shadow-lg">
                                    {candidate.candidate_number}
                                  </div>
                                  <div>
                                    <h4 className="text-lg font-semibold text-gray-900">{candidate.name}</h4>
                                    <p className="text-sm text-gray-600">{candidate.representation}</p>
                                  </div>
                                </div>
                                
                                <div className="flex items-center gap-4">
                                  {isCompleted ? (
                                    <div className="text-center">
                                      <div className="text-2xl font-bold text-green-600">{currentScore}</div>
                                      <div className="text-sm text-gray-500">/{criterion.percentage} points</div>
                                    </div>
                                  ) : (
                                    <div className="flex items-center gap-3">
                                      <div className="text-center">
                                        <input
                                          type="number"
                                          min="0"
                                          max={criterion.percentage}
                                          value={currentScore}
                                          onChange={(e) => handleCriteriaScoreChange(candidate.id, criterion.id, e.target.value)}
                                          className="w-24 px-4 py-3 border-2 border-gray-300 rounded-xl text-center text-lg font-semibold focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
                                        />
                                        <div className="text-sm text-gray-500 mt-1">/{criterion.percentage}</div>
                                      </div>
                                    </div>
                                  )}
                                </div>
                              </div>
                              
                              {!isCompleted && (
                                <div className="mt-6">
                                  <div className="flex items-center justify-between text-sm text-gray-600 mb-2">
                                    <span>0</span>
                                    <span className="font-medium">Current: {currentScore}</span>
                                    <span>{criterion.percentage}</span>
                                  </div>
                                  <input
                                    type="range"
                                    min="0"
                                    max={criterion.percentage}
                                    value={currentScore}
                                    onChange={(e) => handleCriteriaScoreChange(candidate.id, criterion.id, e.target.value)}
                                    className="w-full h-3 bg-gradient-to-r from-gray-200 to-blue-200 rounded-lg appearance-none cursor-pointer slider"
                                    style={{
                                      background: `linear-gradient(to right, #3b82f6 0%, #3b82f6 ${(currentScore / criterion.percentage) * 100}%, #e5e7eb ${(currentScore / criterion.percentage) * 100}%, #e5e7eb 100%)`
                                    }}
                                  />
                                </div>
                              )}
                            </div>
                          )
                        })}
                      </div>

                      {/* Submit Button */}
                      {!isCompleted && (
                        <div className="flex justify-end">
                          <button
                            onClick={() => handleSubmitCriteriaClick(criterion.id)}
                            disabled={submitting || !canSubmitCriteria(criterion.id)}
                            className="px-8 py-4 bg-gradient-to-r from-blue-500 to-blue-600 text-white rounded-xl hover:from-blue-600 hover:to-blue-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-3 font-semibold text-lg shadow-lg hover:shadow-xl transition-all duration-300 transform hover:scale-105"
                          >
                            {submitting ? (
                              <>
                                <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                                Submitting Scores...
                              </>
                            ) : (
                              <>
                                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                                </svg>
                                Submit Scores
                              </>
                            )}
                          </button>
                        </div>
                      )}
                    </div>
                  )}
                </div>
              )
            })}
          </div>
        </div>

        {/* Special Awards Section */}
        {specialAwards.length > 0 && (
          <div className="mb-8">
            <div className="flex items-center gap-4 mb-8">
              <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-purple-600 rounded-2xl flex items-center justify-center shadow-lg">
                <svg className="w-7 h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" />
                </svg>
              </div>
              <div>
                <h2 className="text-3xl font-bold text-gray-900">Special Awards</h2>
                <p className="text-gray-600 mt-1">Vote for candidates in special award categories</p>
              </div>
            </div>
            
            <div className="space-y-4">
              {specialAwards.map((award) => {
                const isExpanded = expandedAwards === award.id
                const isCompleted = isAwardComplete(award.id)
                
                return (
                  <div key={award.id} className={`bg-white rounded-2xl shadow-lg border-2 transition-all duration-300 ${
                    isExpanded ? 'border-purple-300 shadow-xl' : 'border-gray-200 hover:border-purple-200'
                  }`}>
                    {/* Award Header */}
                    <div 
                      className="p-6 cursor-pointer hover:bg-gradient-to-r hover:from-purple-50 hover:to-pink-50 transition-all duration-300 rounded-t-2xl"
                      onClick={() => toggleAwardExpansion(award.id)}
                    >
                      <div className="flex items-center justify-between">
                        <div className="flex items-center gap-4 flex-wrap">
                          <div className="flex items-center gap-3">
                            <div className={`w-10 h-10 rounded-xl flex items-center justify-center ${
                              isCompleted ? 'bg-green-100' : 'bg-purple-100'
                            }`}>
                              {isCompleted ? (
                                <svg className="w-6 h-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                                </svg>
                              ) : (
                                <svg className="w-6 h-6 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" />
                                </svg>
                              )}
                            </div>
                            <div>
                              <h3 className="text-xl font-bold text-gray-900">{award.name}</h3>
                              <p className="text-sm text-gray-600">Maximum 100 points</p>
                            </div>
                          </div>
                          
                          <div className="flex items-center gap-2">
                            <span className={`px-4 py-2 rounded-full text-sm font-semibold ${
                              isCompleted 
                                ? 'bg-green-100 text-green-800 border border-green-200' 
                                : 'bg-purple-100 text-purple-800 border border-purple-200'
                            }`}>
                              {isCompleted ? '✓ Completed' : 'Pending'}
                            </span>
                          </div>
                        </div>
                        
                        <div className="flex items-center gap-3">
                          <div className={`w-8 h-8 rounded-full flex items-center justify-center transition-all duration-300 ${
                            isExpanded ? 'bg-purple-100 rotate-180' : 'bg-gray-100'
                          }`}>
                            <svg 
                              className="w-5 h-5 text-gray-600 transition-transform duration-300" 
                              fill="none" 
                              stroke="currentColor" 
                              viewBox="0 0 24 24"
                            >
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                            </svg>
                          </div>
                        </div>
                      </div>
                      {award.description && (
                        <div className="mt-4 p-4 bg-gray-50 rounded-xl border border-gray-200">
                          <p className="text-gray-700 font-medium">{award.description}</p>
                        </div>
                      )}
                    </div>

                    {/* Expanded Content */}
                    {isExpanded && (
                      <div className="border-t border-gray-200 p-8 bg-gradient-to-br from-gray-50 to-purple-50 rounded-b-2xl">
                        <div className="bg-white rounded-xl p-6 shadow-sm border border-gray-200 mb-6">
                          <div className="flex items-center gap-3 mb-2">
                            <div className="w-8 h-8 bg-purple-100 rounded-lg flex items-center justify-center">
                              <svg className="w-5 h-5 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                              </svg>
                            </div>
                            <h4 className="text-lg font-semibold text-gray-900">Voting Instructions</h4>
                          </div>
                          <p className="text-gray-700">Score each candidate from 0 to 100 points for this special award category.</p>
                        </div>
                        
                        {/* Candidates Scoring */}
                        <div className="space-y-4 mb-8">
                          {candidates.map((candidate) => {
                            const scoreKey = `${candidate.id}-${award.id}`
                            const currentScore = awardScores[scoreKey] || 0
                            
                            return (
                              <div key={candidate.id} className="bg-white rounded-xl p-6 border border-gray-200 shadow-sm hover:shadow-md transition-shadow">
                                <div className="flex items-center justify-between">
                                  <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-purple-600 text-white rounded-xl flex items-center justify-center text-lg font-bold shadow-lg">
                                      {candidate.candidate_number}
                                    </div>
                                    <div>
                                      <h4 className="text-lg font-semibold text-gray-900">{candidate.name}</h4>
                                      <p className="text-sm text-gray-600">{candidate.representation}</p>
                                    </div>
                                  </div>
                                  
                                  <div className="flex items-center gap-4">
                                    {isCompleted ? (
                                      <div className="text-center">
                                        <div className="text-2xl font-bold text-green-600">{currentScore}</div>
                                        <div className="text-sm text-gray-500">/100 points</div>
                                      </div>
                                    ) : (
                                      <div className="flex items-center gap-3">
                                        <div className="text-center">
                                          <input
                                            type="number"
                                            min="0"
                                            max="100"
                                            value={currentScore}
                                            onChange={(e) => handleAwardScoreChange(candidate.id, award.id, e.target.value)}
                                            className="w-24 px-4 py-3 border-2 border-gray-300 rounded-xl text-center text-lg font-semibold focus:ring-2 focus:ring-purple-500 focus:border-purple-500 transition-all"
                                          />
                                          <div className="text-sm text-gray-500 mt-1">/100</div>
                                        </div>
                                      </div>
                                    )}
                                  </div>
                                </div>
                                
                                {!isCompleted && (
                                  <div className="mt-6">
                                    <div className="flex items-center justify-between text-sm text-gray-600 mb-2">
                                      <span>0</span>
                                      <span className="font-medium">Current: {currentScore}</span>
                                      <span>100</span>
                                    </div>
                                    <input
                                      type="range"
                                      min="0"
                                      max="100"
                                      value={currentScore}
                                      onChange={(e) => handleAwardScoreChange(candidate.id, award.id, e.target.value)}
                                      className="w-full h-3 bg-gradient-to-r from-gray-200 to-purple-200 rounded-lg appearance-none cursor-pointer slider"
                                      style={{
                                        background: `linear-gradient(to right, #8b5cf6 0%, #8b5cf6 ${currentScore}%, #e5e7eb ${currentScore}%, #e5e7eb 100%)`
                                      }}
                                    />
                                  </div>
                                )}
                              </div>
                            )
                          })}
                        </div>

                        {/* Submit Button */}
                        {!isCompleted && (
                          <div className="flex justify-end">
                            <button
                              onClick={() => handleSubmitAwardClick(award.id)}
                              disabled={submitting || !canSubmitAward(award.id)}
                              className="px-8 py-4 bg-gradient-to-r from-purple-500 to-purple-600 text-white rounded-xl hover:from-purple-600 hover:to-purple-700 disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-3 font-semibold text-lg shadow-lg hover:shadow-xl transition-all duration-300 transform hover:scale-105"
                            >
                              {submitting ? (
                                <>
                                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                                  Submitting Votes...
                                </>
                              ) : (
                                <>
                                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-5.714 2.143L13 21l-2.286-6.857L5 12l5.714-2.143L13 3z" />
                                  </svg>
                                  Submit Votes
                                </>
                              )}
                            </button>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          </div>
        )}

        {/* Action Buttons */}
        <div className="bg-white rounded-2xl shadow-lg border border-gray-200 p-6">
          <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
            <button
              onClick={() => navigate('/access-event')}
              className="px-8 py-3 bg-gradient-to-r from-gray-500 to-gray-600 text-white rounded-xl hover:from-gray-600 hover:to-gray-700 flex items-center gap-3 font-semibold shadow-lg hover:shadow-xl transition-all duration-300 transform hover:scale-105"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
              </svg>
              Exit Event
            </button>
            
            <div className="text-center sm:text-right">
              <div className="flex flex-col sm:flex-row items-center gap-2 sm:gap-6 text-sm text-gray-600">
                <div className="flex items-center gap-2">
                  <div className="w-3 h-3 bg-blue-500 rounded-full"></div>
                  <span className="font-semibold">
                    {completedCriteria.size} of {criteria.length} criteria completed
                  </span>
                </div>
                {specialAwards.length > 0 && (
                  <div className="flex items-center gap-2">
                    <div className="w-3 h-3 bg-purple-500 rounded-full"></div>
                    <span className="font-semibold">
                      {completedAwards.size} of {specialAwards.length} awards completed
                    </span>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Confirmation Modal */}
      {showConfirmationModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50">
          <div className="bg-white rounded-lg shadow-xl max-w-md w-full mx-4">
            {/* Modal Header */}
            <div className="px-6 py-4 border-b border-gray-200">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-yellow-100 rounded-full flex items-center justify-center">
                  <svg className="w-6 h-6 text-yellow-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
                  </svg>
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">Confirm Score Submission</h3>
                  <p className="text-sm text-gray-600">Please review before proceeding</p>
                </div>
              </div>
            </div>

            {/* Modal Body */}
            <div className="px-6 py-4">
              <div className="space-y-4">
                <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                  <div className="flex items-start gap-3">
                    <svg className="w-5 h-5 text-blue-600 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                    <div>
                      <h4 className="font-medium text-blue-900 mb-1">Submitting scores for:</h4>
                      <p className="text-blue-800 font-semibold">
                        {pendingSubmission?.type === 'criteria' 
                          ? criteria.find(c => c.id === pendingSubmission.id)?.name
                          : specialAwards.find(a => a.id === pendingSubmission.id)?.name
                        }
                      </p>
                      <p className="text-blue-700 text-sm">
                        {pendingSubmission?.type === 'criteria' 
                          ? `Maximum score: ${criteria.find(c => c.id === pendingSubmission.id)?.percentage || 0} points`
                          : 'Maximum score: 100 points'
                        }
                      </p>
                    </div>
                  </div>
                </div>

                <div className="bg-red-50 border border-red-200 rounded-lg p-4">
                  <div className="flex items-start gap-3">
                    <svg className="w-5 h-5 text-red-600 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-2.5L13.732 4c-.77-.833-1.964-.833-2.732 0L3.732 16.5c-.77.833.192 2.5 1.732 2.5z" />
                    </svg>
                    <div>
                      <h4 className="font-medium text-red-900 mb-1">⚠️ Important Notice</h4>
                      <p className="text-red-800 text-sm">
                        <strong>Scores will be permanently locked after submission and cannot be edited.</strong> 
                        This affects {candidates.length} candidates and the scores will be final.
                      </p>
                    </div>
                  </div>
                </div>

                <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                  <div className="flex items-center gap-3">
                    <svg className="w-5 h-5 text-gray-600 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                    <div>
                      <p className="text-gray-700 text-sm">
                        Please ensure all scores are accurate before confirming.
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            </div>

            {/* Modal Footer */}
            <div className="px-6 py-4 border-t border-gray-200 flex justify-end gap-3">
              <button
                onClick={handleCancelSubmission}
                disabled={submitting}
                className="px-4 py-2 text-sm font-medium text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500 disabled:opacity-50"
              >
                Cancel
              </button>
              <button
                onClick={handleConfirmSubmission}
                disabled={submitting}
                className="px-4 py-2 text-sm font-medium text-white bg-red-600 border border-transparent rounded-lg hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500 disabled:opacity-50 flex items-center gap-2"
              >
                {submitting ? (
                  <>
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                    Submitting...
                  </>
                ) : (
                  <>
                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    Confirm Submission
                  </>
                )}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

export default JudgePanel